*** Begin Patch
*** Add File: output/assets/css/styles.css
+:root{
+  --gb-green:#00824A;
+  --gb-forest:#32462F;
+  --gb-cream:#F3CEA1;
+  --gb-ink:#102017;
+  --gb-paper:#FBFAF7;
+  --gb-surface:#FFFFFF;
+  --gb-border:rgba(16,32,23,.12);
+  --gb-shadow:0 14px 40px rgba(16,32,23,.12);
+  --gb-shadow-soft:0 10px 24px rgba(16,32,23,.10);
+  --radius-xl:24px;
+  --radius-lg:18px;
+  --radius-md:14px;
+  --radius-sm:12px;
+  --container:1160px;
+}
+
+*{box-sizing:border-box}
+html{scroll-behavior:smooth}
+body{
+  margin:0;
+  font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,"Apple Color Emoji","Segoe UI Emoji";
+  color:var(--gb-ink);
+  background:
+    radial-gradient(1200px 800px at 20% -10%, rgba(0,130,74,.10), transparent 60%),
+    radial-gradient(900px 700px at 100% 10%, rgba(243,206,161,.22), transparent 55%),
+    var(--gb-paper);
+  line-height:1.5;
+}
+
+h1,h2,h3{
+  font-family:ui-sans-serif,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;
+  letter-spacing:-0.02em;
+  line-height:1.12;
+  margin:0 0 12px;
+  color:var(--gb-forest);
+}
+
+h1{font-size:clamp(34px, 4.4vw, 56px)}
+h2{font-size:clamp(24px, 3.2vw, 36px)}
