+.brand-name{font-weight:800;letter-spacing:-.02em}
+.brand-sub{font-size:12px;color:rgba(16,32,23,.68);margin-top:2px}
+
+.navlinks{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
+.navlinks a{
+  padding:10px 12px;
+  border-radius:999px;
+  text-decoration:none;
+  font-weight:650;
+  color:rgba(16,32,23,.86);
+}
+.navlinks a:hover{background:rgba(16,32,23,.05)}
+.navlinks a[aria-current="page"]{background:rgba(0,130,74,.12);color:var(--gb-forest)}
+
+.navactions{display:flex;align-items:center;gap:10px}
+.navactions a{white-space:nowrap}
+
+.hero{
+  padding:34px 0 10px;
+}
+.hero-wrap{
+  display:grid;
+  grid-template-columns:1.15fr .85fr;
+  gap:18px;
+  align-items:stretch;
+}
+.hero-card{
+  padding:28px;
+  border-radius:var(--radius-xl);
+  background:
+    radial-gradient(1000px 600px at 10% 0%, rgba(0,130,74,.20), transparent 60%),
+    radial-gradient(700px 520px at 110% 10%, rgba(243,206,161,.34), transparent 55%),
+    linear-gradient(180deg, rgba(255,255,255,.92), rgba(255,255,255,.78));
+  border:1px solid rgba(16,32,23,.12);
+  box-shadow:var(--gb-shadow);
+  overflow:hidden;
+  position:relative;
+}
+.hero-card:before{
+  content:"";
+  position:absolute;
+  right:-90px;top:-90px;
+  width:260px;height:260px;
+  border-radius:80px;
+  background:rgba(0,130,74,.12);
+  transform:rotate(12deg);
+}
+.hero-card:after{
+  content:"";
+  position:absolute;
+  left:-110px;bottom:-110px;
+  width:300px;height:300px;
+  border-radius:110px;
+  background:rgba(50,70,47,.10);
