+
+.carousel{
+  position:relative;
+  overflow:hidden;
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(16,32,23,.12);
+  background:rgba(255,255,255,.86);
+  box-shadow:var(--gb-shadow-soft);
+}
+.carousel-track{
+  display:flex;
+  gap:14px;
+  padding:16px;
+  scroll-behavior:smooth;
+  overflow:auto;
+  scrollbar-width:none;
+}
+.carousel-track::-webkit-scrollbar{display:none}
+.gift-card{
+  flex:0 0 220px;
+  border-radius:20px;
+  border:1px solid rgba(16,32,23,.12);
+  background:linear-gradient(135deg, rgba(0,130,74,.16), rgba(243,206,161,.34));
+  padding:14px;
+  position:relative;
+  box-shadow:0 10px 18px rgba(16,32,23,.10);
+}
+.gift-card:before{
+  content:"";
+  position:absolute;
+  inset:10px;
+  border-radius:16px;
+  background:rgba(251,250,247,.55);
+  border:1px dashed rgba(16,32,23,.14);
+}
+.gift-card .gc-body{position:relative;z-index:2;min-height:118px;display:flex;flex-direction:column;justify-content:space-between}
+.gift-card strong{display:block;font-size:15px;color:var(--gb-forest)}
+.gift-card span{font-size:12px;color:rgba(16,32,23,.68)}
+.gift-card .tag{display:inline-flex;align-self:flex-start;margin-top:10px}
+
+.carousel-nav{
+  position:absolute;
+  top:14px;
+  right:14px;
+  display:flex;
+  gap:8px;
+}
+.iconbtn{
+  width:42px;height:42px;
+  border-radius:999px;
+  border:1px solid rgba(16,32,23,.16);
+  background:rgba(251,250,247,.88);
+  box-shadow:0 10px 18px rgba(16,32,23,.10);
+  cursor:pointer;
+}
+.iconbtn:hover{background:#fff}
+.iconbtn:focus-visible{outline:3px solid rgba(0,130,74,.28);outline-offset:2px}
+
+.searchbar{
+  display:flex;
+  gap:10px;
+  flex-wrap:wrap;
+  align-items:center;
+}
+.input{
+  flex:1;
+  min-width:240px;
+  padding:12px 14px;
+  border-radius:14px;
+  border:1px solid rgba(16,32,23,.16);
+  background:#fff;
+  font-weight:550;
+}
+.input:focus{outline:3px solid rgba(0,130,74,.20);border-color:rgba(0,130,74,.26)}
+
+.toggle{
+  display:inline-flex;
+  background:rgba(16,32,23,.06);
+  border:1px solid rgba(16,32,23,.10);
+  border-radius:999px;
+  padding:4px;
+}
+.toggle button{
+  border:0;
+  background:transparent;
+  padding:10px 12px;
+  border-radius:999px;
+  font-weight:800;
+  cursor:pointer;
+  color:rgba(16,32,23,.72);
+}
+.toggle button[aria-pressed="true"]{background:#fff;color:var(--gb-forest);box-shadow:0 10px 18px rgba(16,32,23,.10)}
+
+.suggestions{
+  position:relative;
+  flex:1;
+  min-width:240px;
+}
+.suggestions-panel{
+  position:absolute;
+  left:0;right:0;
+  top:52px;
+  background:#fff;
+  border:1px solid rgba(16,32,23,.12);
+  border-radius:16px;
+  box-shadow:var(--gb-shadow-soft);
+  overflow:hidden;
+  display:none;
+  z-index:10;
+}
+.suggestions-panel[data-open="true"]{display:block}
