+  width:18px;height:18px;
+  border-radius:999px;
+  background:var(--gb-green);
+  box-shadow:0 12px 20px rgba(0,130,74,.26);
+  border:3px solid #fff;
+}
+.map .pin:after{
+  content:"";
+  position:absolute;
+  width:8px;height:8px;
+  border-radius:999px;
+  inset:0;
+  margin:auto;
+  background:#fff;
+  opacity:.0;
+}
+.map .legend{
+  position:absolute;
+  left:14px;
+  bottom:14px;
+  background:rgba(251,250,247,.92);
+  border:1px solid rgba(16,32,23,.12);
+  border-radius:16px;
+  padding:10px 12px;
+  font-weight:650;
+  color:rgba(16,32,23,.72);
+}
+
+.results{display:grid;gap:12px}
+.store{
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(16,32,23,.12);
+  background:rgba(255,255,255,.90);
+  box-shadow:var(--gb-shadow-soft);
+  padding:16px;
+}
+.store .top{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}
+.store .name{font-weight:900;color:var(--gb-forest)}
+.store .meta{color:rgba(16,32,23,.68);font-weight:600}
+.chips{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
+.chip{
+  font-size:12px;
+  padding:6px 10px;
+  border-radius:999px;
+  border:1px solid rgba(16,32,23,.14);
+  background:rgba(16,32,23,.03);
+  color:rgba(16,32,23,.74);
+  font-weight:650;
+}
+
+.footer{
+  margin-top:30px;
+  background:rgba(255,255,255,.86);
+  border-top:1px solid rgba(16,32,23,.10);
+}
+.footer-inner{padding:26px 0}
+.footer-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px}
+.footer-col h4{
+  margin:0 0 10px;
+  font-size:14px;
+  letter-spacing:.04em;
+  text-transform:uppercase;
+  color:rgba(16,32,23,.72);
+}
+.footer-col a{
+  display:block;
+  text-decoration:none;
+  padding:6px 0;
+  color:rgba(16,32,23,.78);
+}
+.footer-col a:hover{text-decoration:underline}
+.footer-bottom{
+  border-top:1px solid rgba(16,32,23,.08);
+  padding:16px 0;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:12px;
+  flex-wrap:wrap;
+  color:rgba(16,32,23,.62);
+}
+
+.cookie{
+  position:fixed;
+  left:18px;
+  right:18px;
+  bottom:18px;
+  z-index:80;
+  max-width:var(--container);
+  margin:0 auto;
+}
+.cookie .card{
+  display:flex;
+  gap:14px;
+  align-items:flex-start;
+  justify-content:space-between;
+  padding:16px;
+}
+.cookie h3{margin:0 0 6px;font-size:18px}
+.cookie p{margin:0;color:rgba(16,32,23,.72)}
+.cookie .actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center;justify-content:flex-end}
+
+.sr-only{
+  position:absolute;
+  width:1px;height:1px;
+  padding:0;margin:-1px;
+  overflow:hidden;
+  clip:rect(0,0,0,0);
+  white-space:nowrap;border:0;
+}
+
+@media (max-width: 980px){
+  .hero-wrap{grid-template-columns:1fr}
+  .layout{grid-template-columns:1fr}
+  .sidebar{position:relative;top:auto}
+  .tier-grid{grid-template-columns:1fr}
+  .footer-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
+}
+
+@media (max-width: 640px){
+  .two,.three{grid-template-columns:1fr}
+  .menu-items{grid-template-columns:1fr}
+  .nav{flex-wrap:wrap}
+  .navlinks{gap:6px}
+  .navlinks a{padding:9px 10px}
+  .cookie .card{flex-direction:column;align-items:stretch}
+  .cookie .actions{justify-content:flex-start}
+
+  /* Mobile footer accordion */
+  .footer-grid{grid-template-columns:1fr}
+  .footer-col{border:1px solid rgba(16,32,23,.10);border-radius:18px;overflow:hidden;background:rgba(251,250,247,.72)}
+  .footer-col h4{
+    margin:0;
+    padding:14px 14px;
+    display:flex;
+    align-items:center;
+    justify-content:space-between;
+    cursor:pointer;
+    user-select:none;
+  }
+  .footer-col h4:after{content:"+";font-size:18px;color:rgba(16,32,23,.56)}
+  .footer-col[data-open="true"] h4:after{content:"–"}
+  .footer-col .links{display:none;padding:0 14px 12px}
+  .footer-col[data-open="true"] .links{display:block}
+  .footer-col a{padding:10px 0}
+}
+
*** End Patch
PATCH

